//! NGSI-LD vocabulary constants derived from local JSON-LD contexts at compile time.
//!
//! Most constants are generated by the [`jsonld::vocab!`] proc-macro, which
//! parses the embedded NGSI-LD v1.9 core context JSON and emits typed
//! `pub const iri_rs::Iri<&'static str>` constants for every resolved term,
//! partitioned into `classes` and `properties` submodules by JSON-LD casing
//! convention (`TitleCase` classes, lowerCase properties). A handful of IRIs the
//! core context does not declare as terms — because they appear as data
//! values or a bare datatype rather than as `@context` term names — are
//! hand-written constants alongside it.
//!
//! This is the leaf of the workspace. It exists as its own crate so that the
//! `jsonld` proc-macro, which nothing else in the tree needs at compile time, is
//! built once here rather than by every crate that reads an NGSI-LD IRI.
//!
//! # Usage
//!
//! ```ignore
//! use andromeda_ngsi_ld_vocabulary::{expanded::properties as expanded_properties, prefix, compact_to_expanded};
//! let iri: iri_rs::Iri<&'static str> = expanded_properties::CREATED_AT;
//! let ngsi_ld: iri_rs::Iri<&'static str> = prefix::NGSI_LD;
//! let expanded: Option<&str> = compact_to_expanded("createdAt");
//! ```

#![deny(missing_docs)]
#![deny(clippy::missing_docs_in_private_items)]

use iri_rs::{Iri, iri};

jsonld::vocab! {
    contexts: ["context/ngsi-ld-core-context-v1.9.jsonld"]
}

/// The core `@context` URL Andromeda emits.
///
/// Clause 4.4 (ETSI GS CIM 009) names the core `@context`, and every Annex C
/// example prints it as the versioned `-v1.9.jsonld` URL. Andromeda emits that
/// exact identifier so a client sees the precise core context version its
/// responses were produced against. The version-less
/// `ngsi-ld-core-context.jsonld` alias
/// (`andromeda_jsonld::core_context::NGSI_LD_CORE_CONTEXT_UNVERSIONED_URL`) is
/// still accepted on inbound documents and resolves to the same v1.9 payload.
pub const NGSI_LD_CORE_CONTEXT_URL: Iri<&'static str> = iri!("https://uri.etsi.org/ngsi-ld/v1/ngsi-ld-core-context-v1.9.jsonld");

/// The NGSI-LD null sentinel, `urn:ngsi-ld:null` (clause 5.5.12).
///
/// Written by a client as an attribute's value to delete that member in a
/// merge patch. It appears as data rather than as an `@context` term, so the
/// core context declares no term for it.
pub const NULL_URI: Iri<&'static str> = iri!("urn:ngsi-ld:null");

/// The expanded-IRI spelling of the NGSI-LD null sentinel (clause 5.5.12).
pub const NULL_IRI: Iri<&'static str> = iri!("https://uri.etsi.org/ngsi-ld/null");

/// The core context's aliases of the JSON-LD `@id` and `@type` keywords, which
/// name no IRI and so are absent from the term table.
const CORE_KEYWORD_ALIASES: [&str; 2] = ["id", "type"];

/// Whether `name` is a JSON-LD keyword or a term of the core context.
///
/// Such a name is spelled the same under every `@context`, because the core
/// context has absolute precedence (clause 5.5.7), and inside an attribute it
/// names one of the attribute's own members rather than a sub-attribute.
#[must_use]
pub fn is_core_term(name: &str) -> bool {
    name.starts_with('@') || CORE_KEYWORD_ALIASES.contains(&name) || compact_to_expanded(name).is_some()
}

#[cfg(test)]
mod tests {
    use crate::{
        COMPACT_TO_EXPANDED,
        EXPANDED_TO_COMPACT,
        TERM_COUNT,
        compact::{classes as compact_classes, properties as compact_properties},
        compact_to_expanded,
        expanded::{classes as expanded_classes, properties as expanded_properties},
        expanded_to_compact,
        prefix,
    };
    use iri_rs::Iri;

    #[test]
    fn term_count_exceeds_170() {
        const { assert!(TERM_COUNT > 170, "expected >170 terms") };
    }

    #[test]
    fn compact_to_expanded_round_trips() {
        for &(compact, expanded) in COMPACT_TO_EXPANDED {
            let result = compact_to_expanded(compact);
            pretty_assertions::assert_eq!(result, Some(expanded), "compact_to_expanded failed for '{compact}'");
        }
    }

    #[test]
    fn expanded_to_compact_round_trips() {
        for &(expanded, compact) in EXPANDED_TO_COMPACT {
            let result = expanded_to_compact(expanded);
            pretty_assertions::assert_eq!(result, Some(compact), "expanded_to_compact failed for '{expanded}'");
        }
    }

    #[test]
    fn lookup_tables_are_sorted() {
        for window in COMPACT_TO_EXPANDED.windows(2) {
            assert!(
                window[0].0 < window[1].0,
                "COMPACT_TO_EXPANDED not sorted: {:?} >= {:?}",
                window[0].0,
                window[1].0
            );
        }
        for window in EXPANDED_TO_COMPACT.windows(2) {
            assert!(
                window[0].0 < window[1].0,
                "EXPANDED_TO_COMPACT not sorted: {:?} >= {:?}",
                window[0].0,
                window[1].0
            );
        }
    }

    #[test]
    fn known_class_constants_match_iris() {
        let _: Iri<&'static str> = expanded_classes::PROPERTY;
        pretty_assertions::assert_eq!(expanded_classes::PROPERTY.as_str(), "https://uri.etsi.org/ngsi-ld/Property");
        pretty_assertions::assert_eq!(expanded_classes::RELATIONSHIP.as_str(), "https://uri.etsi.org/ngsi-ld/Relationship");
        pretty_assertions::assert_eq!(expanded_classes::GEO_PROPERTY.as_str(), "https://uri.etsi.org/ngsi-ld/GeoProperty");
        pretty_assertions::assert_eq!(expanded_classes::DATE_TIME.as_str(), "https://uri.etsi.org/ngsi-ld/DateTime");
    }

    #[test]
    fn known_property_constants_match_iris() {
        pretty_assertions::assert_eq!(expanded_properties::VALUE.as_str(), "https://uri.etsi.org/ngsi-ld/hasValue");
        pretty_assertions::assert_eq!(expanded_properties::OBJECT.as_str(), "https://uri.etsi.org/ngsi-ld/hasObject");
        pretty_assertions::assert_eq!(expanded_properties::LANGUAGE_MAP.as_str(), "https://uri.etsi.org/ngsi-ld/hasLanguageMap");
        pretty_assertions::assert_eq!(expanded_properties::VOCAB.as_str(), "https://uri.etsi.org/ngsi-ld/hasVocab");
        pretty_assertions::assert_eq!(expanded_properties::JSON.as_str(), "https://uri.etsi.org/ngsi-ld/hasJSON");
        pretty_assertions::assert_eq!(expanded_properties::VALUE_LIST.as_str(), "https://uri.etsi.org/ngsi-ld/hasValueList");
        pretty_assertions::assert_eq!(expanded_properties::OBJECT_LIST.as_str(), "https://uri.etsi.org/ngsi-ld/hasObjectList");
        pretty_assertions::assert_eq!(expanded_properties::CREATED_AT.as_str(), "https://uri.etsi.org/ngsi-ld/createdAt");
        pretty_assertions::assert_eq!(expanded_properties::MODIFIED_AT.as_str(), "https://uri.etsi.org/ngsi-ld/modifiedAt");
        pretty_assertions::assert_eq!(expanded_properties::OBSERVED_AT.as_str(), "https://uri.etsi.org/ngsi-ld/observedAt");
        pretty_assertions::assert_eq!(expanded_properties::DELETED_AT.as_str(), "https://uri.etsi.org/ngsi-ld/deletedAt");
        pretty_assertions::assert_eq!(expanded_properties::DATASET_ID.as_str(), "https://uri.etsi.org/ngsi-ld/datasetId");
        pretty_assertions::assert_eq!(expanded_properties::INSTANCE_ID.as_str(), "https://uri.etsi.org/ngsi-ld/instanceId");
        pretty_assertions::assert_eq!(expanded_properties::UNIT_CODE.as_str(), "https://uri.etsi.org/ngsi-ld/unitCode");
        pretty_assertions::assert_eq!(expanded_properties::SCOPE.as_str(), "https://uri.etsi.org/ngsi-ld/scope");
    }

    #[test]
    fn prefix_constants_are_correct() {
        pretty_assertions::assert_eq!(prefix::NGSI_LD.as_str(), "https://uri.etsi.org/ngsi-ld/");
        pretty_assertions::assert_eq!(prefix::GEOJSON.as_str(), "https://purl.org/geojson/vocab#");
    }

    /// Keywords, the two keyword aliases and the core terms read the same in
    /// every context; a user term does not.
    #[test]
    fn core_terms_are_told_apart_from_user_terms() {
        for core in ["@context", "id", "type", "value", "object", "objectList", "entity", "observedAt"] {
            assert!(crate::is_core_term(core), "{core}");
        }
        for user in ["speed", "isParkedIn", "objectTypeName"] {
            assert!(!crate::is_core_term(user), "{user}");
        }
    }

    #[test]
    fn external_iri_constants_are_correct() {
        pretty_assertions::assert_eq!(crate::NULL_URI.as_str(), "urn:ngsi-ld:null");
        pretty_assertions::assert_eq!(crate::NULL_IRI.as_str(), "https://uri.etsi.org/ngsi-ld/null");
    }

    #[test]
    fn nested_core_context_terms_are_available() {
        pretty_assertions::assert_eq!(expanded_properties::ENTITY_ID_SEALED.as_str(), "https://uri.etsi.org/ngsi-ld/entityIdSealed");
        pretty_assertions::assert_eq!(
            expanded_properties::ENTITY_TYPE_SEALED.as_str(),
            "https://uri.etsi.org/ngsi-ld/entityTypeSealed"
        );
    }

    #[test]
    fn geojson_terms_resolve_to_purl_vocab() {
        assert!(expanded_properties::COORDINATES.as_str().starts_with(prefix::GEOJSON.as_str()));
        assert!(expanded_properties::BBOX.as_str().starts_with(prefix::GEOJSON.as_str()));
        assert!(expanded_properties::GEOMETRY.as_str().starts_with(prefix::GEOJSON.as_str()));
        assert!(expanded_properties::FEATURES.as_str().starts_with(prefix::GEOJSON.as_str()));
    }

    #[test]
    fn compact_module_constants_are_correct() {
        pretty_assertions::assert_eq!(compact_classes::PROPERTY, "Property");
        pretty_assertions::assert_eq!(compact_classes::RELATIONSHIP, "Relationship");
        pretty_assertions::assert_eq!(compact_properties::CREATED_AT, "createdAt");
        pretty_assertions::assert_eq!(compact_classes::GEO_PROPERTY, "GeoProperty");
    }
}

